window.STUDY_BFA_AI=[{"title":"Comprendre la communication","notes":[["Pourquoi communiquer efficacement ?","Une information peut être exacte sans être comprise ou utilisée. En entreprise, communiquer efficacement signifie transmettre un contenu fiable, l’adapter au destinataire et permettre une décision ou une action. Dire « le logiciel change lundi » informe ; préciser les tâches, les délais et l’aide disponible permet à l’équipe de s’organiser."],["Définition de la communication","Communiquer est un processus par lequel des personnes construisent, transmettent, interprètent et partagent du sens dans une situation donnée. Le destinataire ne reçoit pas mécaniquement un message : il l’interprète selon ses connaissances, ses attentes et le contexte. Deux personnes peuvent donc comprendre différemment une même consigne."],["Information et communication","L’information correspond à un fait ou à une connaissance : « 72 % des clients utilisent leur smartphone ». La communication met cette information en relation avec un destinataire et un objectif : « Nous devons améliorer l’expérience mobile ». Elle ajoute une intention, un contexte et, dans l’échange professionnel, une possibilité de réaction."],["De la donnée à l’action","Une donnée devient utile lorsqu’elle est interprétée et mise en perspective. Le chemin étudié est : donnée → information → interprétation → décision ou action. Un taux de conversion faible n’est pas une instruction en soi ; il faut expliquer ce qu’il révèle et quelle mesure l’équipe doit examiner."],["Adapter une consigne","Une consigne opérationnelle indique ce qu’il faut faire, qui est concerné et à quelle échéance. « Faites le nécessaire » reste ambigu. Une version plus efficace serait : « Activez votre compte avant vendredi et consultez le tutoriel ; une formation aura lieu jeudi à 14 h ». Le message devient vérifiable et exploitable."],["Vérifier la compréhension","Le retour du destinataire aide à détecter les malentendus. Il peut prendre la forme d’une question, d’une confirmation ou d’une reformulation : « Je dois donc envoyer le tableau signé avant 16 h ? ». Le simple fait d’avoir envoyé un courriel ne prouve pas que son contenu a été compris."]],"cards":[["Pourquoi une information correcte peut-elle être mal comprise ?","Parce qu’elle peut être vague ou inadaptée au destinataire."],["Dans le cours de TEC, quelle différence entre une information et une communication ?","L’information est le contenu ; la communication est le processus de transmission et d’interprétation dans un contexte."],["En communication professionnelle, en quoi une donnée se distingue-t-elle d’une décision ?","La donnée décrit un fait ; la décision sélectionne une action à partir de l’interprétation des faits."],["Dans une consigne de travail, pourquoi la phrase « faites le nécessaire » est-elle insuffisante ?","Elle ne précise ni la tâche, ni le responsable, ni l’échéance attendue."],["Quels détails rendent une consigne exploitable ?","Action attendue, personne concernée et délai."],["Quel est le rôle de la reformulation ?","Vérifier que le destinataire a compris la consigne."],["Un courriel de travail a été envoyé : cela prouve-t-il que le destinataire a compris ?","Non. L’envoi ne garantit pas l’interprétation correcte : il faut au besoin demander un retour ou une reformulation."],["Comment adapter un message à un client ?","Utiliser des mots accessibles et préciser l’impact concret."]],"quiz":[["Une responsable annonce : « Le nouvel outil arrive lundi. Faites le nécessaire ». Quel est le principal défaut ?",["Le message ne précise pas les actions attendues","Le message utilise forcément le mauvais canal","La date annoncée est nécessairement fausse","La responsable n’a pas d’intention"],0,"La formule ne dit pas quelles tâches accomplir ni par qui."],["Quelle reformulation aide le mieux l’équipe à agir ?",["Préparez-vous pour la semaine prochaine","Activez votre compte avant vendredi à 17 h","Prenez les mesures qui s’imposent","Le changement est très important"],1,"La tâche et l’échéance sont explicites."],["« 72 % des clients consultent le site sur mobile ». Il s’agit principalement de…",["Une négociation","Une décision stratégique","Une information chiffrée","Une consigne de formation"],2,"Le pourcentage décrit une situation sans demander encore d’action."],["Un salarié demande « Quel fichier dois-je envoyer ? ». Cette réaction indique surtout…",["Une preuve d’incompétence","Un défaut de connexion","Une décision finale","Un besoin de clarification"],3,"La question révèle une information manquante dans la consigne."],["Quel message montre le passage de l’information à l’action ?",["Le taux d’abandon atteint 38 %, analysons le paiement mobile","Le taux d’abandon est de 38 %","Le taux est plus élevé que prévu","Les résultats ont été envoyés"],0,"L’information est interprétée et débouche sur une action proposée."],["Pourquoi demander au destinataire de reformuler ?",["Pour rendre le message plus long","Pour contrôler le sens réellement compris","Pour remplacer la consigne initiale","Pour éviter tout échange"],1,"La reformulation aide à vérifier la compréhension."],["Deux équipes comprennent différemment « urgent ». Cela illustre…",["Une panne technique","Une erreur arithmétique","L’influence du contexte et de l’interprétation","Une absence obligatoire d’émetteur"],2,"Le sens varie selon les attentes et le contexte."],["Quelle condition ne suffit PAS à prouver une communication efficace ?",["La tâche est précise","Le délai est explicite","Le public comprend les termes","Le courriel a été envoyé"],3,"L’envoi ne garantit pas que le message a été compris."]],"map":[["Pourquoi communiquer efficacement ?","Une information peut être exacte sans être comprise ou utilisée"],["Définition de la communication","Communiquer est un processus par lequel des personnes construisent, transmettent, interprètent "],["Information et communication","L’information correspond à un fait ou à une connaissance : « 72 % des clients utilisent leur sm"],["De la donnée à l’action","Une donnée devient utile lorsqu’elle est interprétée et mise en perspective"],["Adapter une consigne","Une consigne opérationnelle indique ce qu’il faut faire, qui est concerné et à quelle échéance"],["Vérifier la compréhension","Le retour du destinataire aide à détecter les malentendus"]]},{"title":"Schéma et modèles de la communication","notes":[["Les composantes du schéma","Le cours identifie sept composantes : émetteur, intention, message, canal et code, récepteur, interprétation et rétroaction. Le contexte englobe l’ensemble : lieu, moment et situation. Pour analyser une réunion, on cherche qui parle, dans quel but, à qui, par quel moyen et avec quel résultat."],["Émetteur, intention et message","L’émetteur produit le message avec une intention : informer, demander, convaincre ou coordonner. Le message correspond au contenu effectivement transmis. Un responsable peut vouloir accélérer le traitement des dossiers, mais écrire seulement « soyez plus efficaces » : son intention existe, pourtant le message manque de précision."],["Canal, code et récepteur","Le canal est le moyen de transmission : entretien, courriel, téléphone ou messagerie. Le code correspond au langage et aux signes utilisés. Le récepteur interprète ce qu’il reçoit. Un rapport très technique peut convenir à un développeur mais être incompréhensible pour un client ; le vocabulaire doit donc être adapté."],["Interprétation et rétroaction","L’interprétation est le sens attribué au message par son destinataire. La rétroaction est la réaction qui permet de savoir comment le message a été reçu : question, réponse ou reformulation. Elle aide à corriger une consigne mal comprise, même si elle ne garantit pas à elle seule l’efficacité de toute communication."],["Shannon et Weaver : transmission","Le modèle de Shannon et Weaver décrit la circulation d’une information entre une source et une destination, par un canal susceptible d’être perturbé par du bruit. Une connexion instable ou un document illisible peut empêcher la réception correcte du message. Ce modèle explique surtout la transmission, pas toute la construction du sens."],["Jakobson et l’approche interactionnelle","Jakobson étudie différentes fonctions du langage, détaillées au chapitre suivant. L’approche interactionnelle souligne le rôle actif du destinataire : écouter, poser des questions et reformuler contribuent à construire un sens partagé. Dans une réunion, la communication n’est donc pas seulement un discours à sens unique."]],"cards":[["Dans le schéma du processus de communication étudié en TEC, quelles sont les sept composantes ?","Émetteur, intention, message, canal/code, récepteur, interprétation et rétroaction, en contexte."],["Dans le schéma de communication étudié en TEC, quel est le rôle du contexte ?","Le lieu, le moment et la situation peuvent modifier le sens attribué au message."],["Dans un courriel professionnel, comment distinguer le canal du code ?","Le courriel est le canal ; la langue et les signes employés constituent le code."],["Quelle différence entre intention et message ?","L’intention est le but ; le message est le contenu transmis."],["Dans le processus de communication étudié, qu’appelle-t-on « rétroaction » ?","La réaction du destinataire qui renseigne l’émetteur sur la réception et la compréhension du message."],["Dans le modèle de Shannon et Weaver, à quoi correspond le « bruit » ?","À une perturbation qui altère la transmission du signal ou du message."],["Quelle limite présente le modèle de transmission de Shannon et Weaver pour expliquer une conversation ?","Il décrit la transmission mais ne rend pas compte à lui seul de toute l’interprétation humaine."],["Quelle place l’approche interactionnelle donne-t-elle au destinataire dans une communication ?","Le destinataire contribue au sens par ses réactions, questions et reformulations."]],"quiz":[["Dans le schéma de communication étudié en TEC, que représente l’émetteur lors d’une réunion ?",["Le canal utilisé par la réunion","La personne qui élabore et transmet le message","La réponse donnée après le message"],1,"L’émetteur formule le message ; le canal et le feedback sont d’autres composantes."],["Dans un message vocal, le téléphone constitue surtout…",["L’intention","L’interprétation","Le canal","La rétroaction"],2,"Le téléphone est un moyen de transmission."],["Après une consigne, un salarié répond « Je vous envoie le rapport mardi ». Quelle composante du schéma de communication est illustrée ?",["La rétroaction","Le code linguistique","Le bruit"],0,"La réponse du destinataire fournit un retour sur la manière dont il interprète la consigne."],["Une visioconférence est coupée par une connexion instable. Quel problème domine ?",["Un bruit de transmission","Une fonction poétique","Un défaut d’ethos","Une intention contradictoire"],0,"La connexion perturbe l’acheminement du message."],["Pourquoi le mot « ici » peut-il être ambigu dans un courriel ?",["Le mot renvoie nécessairement au lieu de l’expéditeur","Le lieu désigné n’est pas forcément partagé ou identifiable par le destinataire","Le canal écrit impose de supprimer toute référence au lieu","L’information est erronée dès lors que le message est électronique"],1,"Le référent dépend du contexte des interlocuteurs."],["En visioconférence, la connexion coupe des mots du message. Dans le modèle de Shannon et Weaver, comment nomme-t-on cette perturbation ?",["Un bruit","Une intention","Une fonction expressive"],0,"Le bruit perturbe la transmission ; il ne décrit ni l’intention du locuteur ni le sens du message."],["Quel élément relève surtout de l’intention ?",["La salle choisie","La langue du courriel","Le nom du destinataire","Obtenir la validation du rapport"],3,"L’intention désigne le résultat recherché par l’émetteur."],["Pourquoi la communication ne se limite-t-elle pas à Shannon et Weaver ?",["L’interprétation et l’interaction dépassent le seul transport du message","Le modèle garantit que chaque destinataire comprend le message de la même façon","La rétroaction suffit toujours à supprimer les différences de contexte","La présence d’un canal transforme automatiquement l’information en compréhension"],0,"La construction du sens implique le contexte et l’activité des interlocuteurs."]],"map":[["Les composantes du schéma","Le cours identifie sept composantes : émetteur, intention, message, canal et code, récepteur, i"],["Émetteur, intention et message","L’émetteur produit le message avec une intention : informer, demander, convaincre ou coordonner"],["Canal, code et récepteur","Le canal est le moyen de transmission : entretien, courriel, téléphone ou messagerie"],["Interprétation et rétroaction","L’interprétation est le sens attribué au message par son destinataire"],["Shannon et Weaver : transmission","Le modèle de Shannon et Weaver décrit la circulation d’une information entre une source et une "],["Jakobson et l’approche interactionnelle","Jakobson étudie différentes fonctions du langage, détaillées au chapitre suivant"]]},{"title":"Fonctions, enjeux et obstacles","notes":[["Les fonctions référentielle et expressive","La fonction référentielle transmet un fait : « Le serveur est indisponible ». La fonction expressive révèle l’état ou l’attitude de l’émetteur : « Je suis préoccupé par ce retard ». Pour identifier une fonction, il faut regarder ce que le message cherche principalement à accomplir, et pas seulement les mots employés."],["Les fonctions conative et phatique","La fonction conative vise une réaction du destinataire : « Envoyez le rapport avant 17 h ». La fonction phatique sert à établir ou maintenir le contact : « Vous m’entendez ? ». Une même prise de parole peut remplir plusieurs fonctions ; on identifie généralement la fonction dominante dans l’exercice."],["Les fonctions métalinguistique et poétique","La fonction métalinguistique explique un mot ou un code : « KPI signifie indicateur clé de performance ». La fonction poétique met l’accent sur la formulation, par exemple dans un slogan. Ces six fonctions, étudiées à partir de Jakobson, permettent d’analyser le rôle d’un message professionnel."],["Les enjeux de la communication","Communiquer peut servir à informer, expliquer, convaincre, coopérer, négocier et construire une relation. Dans une entreprise, ces objectifs se combinent : présenter des résultats ne suffit pas toujours à convaincre une équipe d’adopter une nouvelle méthode. Le message doit répondre à l’enjeu réel de la situation."],["Adapter son message au public","Une panne informatique ne se présente pas de la même façon à un technicien, à un manager et à un client. Le technicien attend le type d’erreur ; le manager veut comprendre l’impact sur l’activité ; le client a besoin d’une information claire sur le service. On adapte le contenu, le niveau de détail, le ton et le canal."],["Reconnaître les obstacles","Les obstacles étudiés comprennent l’ambiguïté, le jargon, le manque ou l’excès d’informations, le mauvais canal, le mauvais destinataire, l’absence de retour et les perturbations techniques ou émotionnelles. Avant d’accuser quelqu’un de ne pas comprendre, il faut identifier l’obstacle et reformuler le message."],["Les formes de communication","La communication orale peut mobiliser les mots, la voix et les gestes : réunion, entretien ou négociation. La communication écrite comprend notamment le courriel, la note, le rapport et le compte rendu. Le choix dépend du but, de l’urgence, de la complexité et de la nécessité de garder une trace."]],"cards":[["Selon les six fonctions de Jakobson, quelle fonction domine dans « le serveur est indisponible » ?","La fonction référentielle : le message informe d’un fait."],["Dans les six fonctions de Jakobson, l’énoncé « Je suis inquiet » illustre quelle fonction ?","Fonction expressive : le locuteur manifeste un ressenti personnel."],["Dans les six fonctions de Jakobson, l’énoncé « Envoyez le dossier » illustre quelle fonction ?","Fonction conative : le locuteur demande au destinataire de réaliser une action."],["Dans les six fonctions de Jakobson, l’énoncé « Vous m’entendez ? » illustre quelle fonction ?","Fonction phatique : le locuteur vérifie que le contact reste établi."],["Dans les six fonctions de Jakobson, l’énoncé « KPI signifie… » illustre quelle fonction ?","Fonction métalinguistique : le message explique le sens d’un mot ou d’un code."],["Selon Jakobson, que met en avant la fonction poétique d’un message professionnel ?","La forme même du message, par exemple un slogan ou une formule mémorable."],["Comment parler d’une panne à un client ?","Décrire son effet et les mesures prises sans jargon inutile."],["Dans le cours de TEC, quels trois obstacles peuvent déformer la compréhension d’un message ?","Ambiguïté des termes, canal mal choisi et absence de rétroaction."]],"quiz":[["Dans les fonctions de Jakobson, « Le serveur est indisponible » remplit principalement quelle fonction ?",["La fonction phatique","La fonction expressive","La fonction référentielle"],2,"L’énoncé décrit un fait : sa fonction principale est référentielle."],["« Je suis préoccupé par ce retard » relève surtout de…",["La fonction phatique","La fonction métalinguistique","La fonction poétique","La fonction expressive"],3,"L’émetteur exprime son ressenti."],["« Envoyez le rapport avant 17 h » vise principalement…",["Une action du destinataire","L’explication d’un terme","La mise en valeur du style","Le maintien du contact"],0,"La fonction conative oriente le comportement du destinataire."],["« Vous m’entendez bien ? » correspond surtout à…",["La fonction référentielle","La fonction phatique","La fonction poétique","La fonction expressive"],1,"La question vérifie le maintien du contact."],["« Par KPI, nous entendons indicateur de performance » illustre…",["La fonction expressive","La fonction conative","La fonction métalinguistique","La fonction phatique"],2,"L’énoncé explique un terme du code employé."],["Une panne est annoncée à un client avec des codes d’erreur sans explication. Quel obstacle domine ?",["Le manque de canal","La présence d’un exemple","L’absence de sujet","Le jargon inadapté"],3,"Le langage technique n’est pas adapté au destinataire."],["Un manager reçoit cinq pages pour signaler un incident simple. Quel obstacle ?",["Un excès d’information","Une absence d’intention","Une erreur de destinataire","Un manque de code"],0,"La quantité de détails masque le point essentiel."],["Quel canal convient le mieux à une urgence nécessitant une réponse immédiate ?",["Un rapport annuel","Un appel direct avec confirmation","Une affiche pour la semaine suivante","Une note archivée"],1,"Un échange immédiat facilite la réaction et la vérification."]],"map":[["Les fonctions référentielle et expressive","La fonction référentielle transmet un fait : « Le serveur est indisponible »"],["Les fonctions conative et phatique","La fonction conative vise une réaction du destinataire : « Envoyez le rapport avant 17 h »"],["Les fonctions métalinguistique et poétique","La fonction métalinguistique explique un mot ou un code : « KPI signifie indicateur clé de perf"],["Les enjeux de la communication","Communiquer peut servir à informer, expliquer, convaincre, coopérer, négocier et construire une"],["Adapter son message au public","Une panne informatique ne se présente pas de la même façon à un technicien, à un manager et à u"],["Reconnaître les obstacles","Les obstacles étudiés comprennent l’ambiguïté, le jargon, le manque ou l’excès d’informations, "]]},{"title":"Prendre la parole et se présenter","notes":[["Trois dimensions de l’oral","La communication orale combine le verbal (les mots et leur organisation), le paraverbal (voix, débit, intonation et pauses) et le non verbal (regard, gestes, posture et expressions). Ces dimensions se renforcent ou se contredisent. Une présentation claire peut perdre en efficacité si elle est prononcée trop vite."],["La dimension verbale","Le verbal concerne le choix du vocabulaire, la précision des phrases, les connecteurs et l’ordre des idées. Dans une présentation professionnelle, une phrase courte et structurée aide le public à suivre le raisonnement. Il vaut mieux définir un terme technique utile que multiplier les expressions compliquées."],["La dimension paraverbale","Le paraverbal désigne la manière de parler : volume, rythme, débit, pauses et accentuation. Une pause après une idée importante laisse au public le temps de la comprendre. Un débit trop rapide peut masquer la structure d’un exposé, même lorsque le texte est bien rédigé."],["La dimension non verbale","Le regard, la posture, les gestes et l’orientation du corps accompagnent la parole. Une posture ouverte et des gestes sobres peuvent soutenir la compréhension. Il ne faut toutefois pas interpréter un geste isolé comme une preuve certaine de confiance ou de mensonge : son sens dépend du contexte."],["Se présenter professionnellement","Une présentation de soi peut suivre la progression : identité → parcours → compétences → expériences ou projets → objectif professionnel. Elle ne consiste pas à réciter tout son CV. Pour un entretien de stage, on sélectionne les informations les plus pertinentes pour l’entreprise et le poste visé."],["Exemple de présentation courte","« Je suis étudiant en Banque, Finance et Assurance. Pendant ma formation, j’ai travaillé sur l’analyse de documents financiers et des projets en équipe. Je souhaite effectuer un stage pour mieux comprendre le fonctionnement d’un service financier et développer mes compétences pratiques. » L’exemple reste à personnaliser selon l’expérience réelle."]],"cards":[["Lors d’une présentation orale professionnelle, qu’englobe la dimension verbale ?","Le choix des mots, le vocabulaire et l’organisation du discours."],["Lors d’un exposé, quels éléments relèvent du paraverbal plutôt que des mots utilisés ?","Débit, volume, intonation et pauses."],["Lors d’un entretien, quels éléments relèvent du non-verbal ?","Regard, posture, gestes et expressions du visage."],["Pourquoi marquer des pauses à l’oral ?","Pour laisser le temps d’assimiler les idées importantes."],["Pourquoi adapter le vocabulaire au public ?","Pour rendre les idées compréhensibles sans perdre leur sens."],["Dans une présentation personnelle professionnelle, quels éléments sélectionner ?","Parcours, compétences, expériences ou projets pertinents, puis objectif professionnel."],["Faut-il raconter tout son CV en une minute ?","Non, sélectionner les éléments utiles au contexte."],["Pourquoi répéter une présentation courte ?","Pour vérifier la durée, la clarté et le rythme."]],"quiz":[["Lors d’un entretien, le candidat choisit des mots précis et structure ses idées. Quelle dimension de l’oral mobilise-t-il ?",["La dimension verbale","La dimension paraverbale","La dimension non verbale"],0,"La dimension verbale comprend les mots et l’organisation des phrases ; le débit relève du paraverbal."],["Une personne parle trop vite. Quelle dimension doit-elle travailler ?",["Le paraverbal","Le code écrit","La fonction métalinguistique","Le canal numérique"],0,"Le débit et les pauses relèvent du paraverbal."],["Le regard et la posture relèvent de…",["La fonction référentielle","La dimension non verbale","La dimension verbale","L’argumentation"],1,"Les gestes et la posture accompagnent le discours sans être des mots."],["Un étudiant présente tout son CV en 45 secondes. Quel problème est le plus probable ?",["Une absence de formation","Une erreur de langue","Un manque de sélection des informations pertinentes","Un manque de compétence"],2,"La présentation doit privilégier les éléments adaptés au stage."],["Quelle ouverture est la plus adaptée à une présentation de stage ?",["Je n’ai pas préparé d’objectif précis","J’ai beaucoup de choses à raconter sur ma vie","Je vais lire toutes mes expériences depuis l’enfance","Je suis étudiant en BFA et je souhaite découvrir la gestion financière en entreprise"],3,"L’énoncé présente le parcours et un objectif professionnel pertinent."],["Pourquoi faire une pause après une idée importante ?",["Pour faciliter l’assimilation","Pour éviter toute question","Pour remplacer les exemples","Pour masquer un manque de plan"],0,"La pause laisse au public le temps de traiter l’information."],["Une posture fermée prouve-t-elle à elle seule un manque de confiance ?",["Oui, dans tous les cas","Non, un geste s’interprète dans son contexte","Oui, si le discours est court","Non, car le non verbal n’existe pas"],1,"Un signe isolé n’autorise pas une conclusion certaine."],["Dans une présentation professionnelle, quelle combinaison est la plus cohérente ?",["Texte précis et débit illisible","Arguments solides et regard constamment détourné","Message clair, rythme maîtrisé et gestes adaptés","Voix forte sans structure"],2,"Les trois dimensions doivent se renforcer."]],"map":[["Trois dimensions de l’oral","La communication orale combine le verbal (les mots et leur organisation), le paraverbal (voix, "],["La dimension verbale","Le verbal concerne le choix du vocabulaire, la précision des phrases, les connecteurs et l’ordr"],["La dimension paraverbale","Le paraverbal désigne la manière de parler : volume, rythme, débit, pauses et accentuation"],["La dimension non verbale","Le regard, la posture, les gestes et l’orientation du corps accompagnent la parole"],["Se présenter professionnellement","Une présentation de soi peut suivre la progression : identité → parcours → compétences → expéri"],["Exemple de présentation courte","« Je suis étudiant en Banque, Finance et Assurance"]]},{"title":"Convaincre et participer à une réunion","notes":[["Identifier son intention communicative","Avant de parler, il faut savoir si l’on cherche à informer, expliquer, demander, convaincre ou coordonner. « Le délai moyen est de trois jours » informe ; « Nous devrions simplifier la procédure » propose une action. Le choix des arguments et du ton dépend de cette intention."],["Logos : raisonner avec des preuves","Le logos repose sur la logique, les faits et les arguments vérifiables. Dire « Le test auprès de 30 utilisateurs a réduit le délai de traitement » mobilise principalement le logos. Un chiffre n’est convaincant que si l’on précise ce qu’il mesure et les limites éventuelles du test."],["Ethos : construire sa crédibilité","L’ethos correspond à la crédibilité que l’orateur inspire par sa maîtrise du sujet, son sérieux et sa manière de présenter les faits. Reconnaître les limites d’une analyse peut renforcer cette crédibilité. L’ethos ne consiste pas seulement à afficher un titre ou une fonction."],["Pathos : toucher la sensibilité","Le pathos mobilise les émotions et les préoccupations du public. Évoquer les conséquences d’un vol de données personnelles peut sensibiliser une équipe à la cybersécurité. Un discours professionnel gagne à articuler émotion, crédibilité et raisonnement plutôt qu’à remplacer les preuves par la peur."],["Organiser la parole en réunion","Une réunion efficace commence par un objectif clair et un ordre du jour. Le responsable peut « faire le point » sur le projet, « cadrer le sujet » puis « faire un tour de table » pour recueillir les avis. À la fin, il précise les décisions, les responsables et les échéances pour éviter les malentendus."],["Expressions de suivi et de coopération","« Mettre à jour » signifie actualiser un document ; « suivre l’avancement », vérifier la progression ; « passer la main », transmettre la responsabilité d’une étape. « Remettre à plat » veut dire réexaminer en profondeur, tandis qu’« arrondir les angles » consiste à faciliter un accord avec diplomatie."],["Expressions liées aux difficultés","« Tenir le cap » signifie conserver l’objectif malgré les obstacles ; « mettre les bouchées doubles », redoubler d’efforts ; « jouer cartes sur table », parler franchement des contraintes ; « être dans les temps », respecter le calendrier. Ces expressions sont utiles si elles correspondent réellement à la situation."]],"cards":[["Dans le modèle de persuasion ethos–logos–pathos, que recherche le logos ?","Convaincre par un raisonnement logique, des données et des preuves."],["Dans ethos–logos–pathos, quel levier vise la crédibilité de l’orateur ?","L’ethos : l’expérience, la compétence et le sérieux perçus du locuteur."],["Dans ethos–logos–pathos, quel levier tient compte des émotions du public ?","Le pathos : mobiliser de façon appropriée ses émotions ou préoccupations."],["Dans les réunions professionnelles, que signifie l’expression « faire un tour de table » ?","Donner successivement la parole aux personnes présentes."],["Dans les réunions professionnelles, que signifie l’expression « remettre à plat » ?","Reprendre un dossier ou une question depuis ses éléments de base."],["Dans les réunions professionnelles, que signifie l’expression « arrondir les angles » ?","Apaiser des tensions et faciliter un compromis."],["Dans les réunions professionnelles, que signifie l’expression « passer la main » ?","Confier la suite d’un dossier à une autre personne ou équipe."],["Dans les réunions professionnelles, que signifie l’expression « mettre les bouchées doubles » ?","Accélérer les efforts pour rattraper un retard."]],"quiz":[["Pendant un pitch, une étudiante cite les résultats chiffrés d’un test. Dans ethos–logos–pathos, quel levier utilise-t-elle principalement ?",["L’ethos","Le logos","Le pathos"],1,"Le logos repose sur le raisonnement et les preuves ; l’ethos sur la crédibilité, le pathos sur les émotions."],["Reconnaître honnêtement les limites de son analyse renforce surtout…",["Le pathos","L’ethos","La fonction poétique","La rétroaction technique"],1,"La rigueur et la transparence soutiennent la crédibilité."],["Évoquer les conséquences humaines d’un vol de données mobilise principalement…",["Le canal","La fonction métalinguistique","Le pathos","Le bruit"],2,"L’exemple fait appel aux préoccupations et émotions du public."],["« Faisons un tour de table » signifie…",["Mettre à jour un tableau","Modifier le plan de salle","Transférer le projet","Donner successivement la parole"],3,"Chaque participant est invité à s’exprimer."],["« Remettre à plat les responsabilités » signifie…",["Réexaminer complètement leur répartition","Actualiser seulement la date du fichier","Confier toutes les tâches à une personne","Suspendre définitivement la réunion"],0,"Remettre à plat implique une révision de fond."],["Une équipe doit « arrondir les angles ». Elle doit…",["Reporter toute décision sans en parler à l’équipe","Atténuer les tensions et chercher une formulation diplomatique","Reformuler une consigne en supprimant toute objection","Accélérer le débat en réduisant le temps de parole des participants"],1,"L’expression vise à atténuer les tensions pour faciliter l’accord."],["« Passer la main » à l’équipe de test veut dire…",["Doubler les efforts de l’équipe actuelle","Mettre fin au projet","Transmettre la responsabilité de l’étape suivante","Reprendre toutes les décisions"],2,"La responsabilité est transférée à une autre équipe."],["Une équipe en retard doit « mettre les bouchées doubles ». Elle doit…",["Modifier son identité visuelle","Mettre à jour le procès-verbal","Réduire le nombre de réunions à zéro","Redoubler d’efforts pour respecter le délai"],3,"L’expression renvoie à un effort accru."]],"map":[["Identifier son intention communicative","Avant de parler, il faut savoir si l’on cherche à informer, expliquer, demander, convaincre ou "],["Logos : raisonner avec des preuves","Le logos repose sur la logique, les faits et les arguments vérifiables"],["Ethos : construire sa crédibilité","L’ethos correspond à la crédibilité que l’orateur inspire par sa maîtrise du sujet, son sérieux"],["Pathos : toucher la sensibilité","Le pathos mobilise les émotions et les préoccupations du public"],["Organiser la parole en réunion","Une réunion efficace commence par un objectif clair et un ordre du jour"],["Expressions de suivi et de coopération","« Mettre à jour » signifie actualiser un document ; « suivre l’avancement », vérifier la progre"]]},{"title":"Construire un exposé et un pitch","notes":[["Définir le sujet et la problématique","Un thème indique de quoi l’on parle ; une problématique formule une question précise à laquelle l’exposé doit répondre. « Les réseaux sociaux dans les entreprises » est un thème. « Comment une entreprise peut-elle utiliser les réseaux sociaux tout en protégeant sa réputation ? » est une problématique exploitable."],["Préparer l’introduction","L’introduction capte l’attention, présente le sujet, formule la problématique et annonce le plan. Elle doit rester proportionnée à la durée de l’exposé. Une donnée pertinente, une situation concrète ou une question peut servir d’accroche, à condition de conduire directement au sujet."],["Organiser le développement","Le développement suit deux ou trois idées principales, chacune appuyée par une explication et un exemple. Une idée par partie permet au public de suivre le raisonnement. Les transitions indiquent pourquoi on passe d’un argument au suivant et évitent une simple accumulation de diapositives."],["Conclure utilement","La conclusion répond à la problématique, rappelle l’essentiel et peut ouvrir sur une question ou une perspective pertinente. Elle ne doit pas introduire un nouvel argument important. Une phrase finale courte et maîtrisée laisse une impression plus claire qu’une répétition de tout l’exposé."],["Le pitch professionnel","Un pitch est une présentation courte destinée à faire comprendre rapidement une idée ou un projet. On peut partir d’un besoin, présenter la solution, montrer sa valeur, donner un élément de preuve et terminer par une demande ou une prochaine étape. L’ordre exact dépend du public et de l’objectif."],["Adapter le pitch au temps disponible","Pour un pitch d’une minute, il faut choisir un message central et un seul exemple convaincant. Pour une présentation plus longue, on peut détailler le contexte et les résultats. Répéter à voix haute avec un chronomètre permet d’ajuster le texte sans accélérer artificiellement le débit."]],"cards":[["Lors de la préparation d’un exposé, comment distinguer thème et problématique ?","Le thème nomme le sujet ; la problématique formule la question précise à résoudre."],["Dans un exposé professionnel, quelles parties construisent une introduction claire ?","Accroche, présentation du sujet, problématique et annonce du plan."],["Pour structurer le développement d’un exposé, quels éléments associer à chaque idée ?","Une explication, un exemple ou une preuve, puis une transition vers l’idée suivante."],["Dans un exposé, que doit accomplir la conclusion par rapport à la problématique ?","Y répondre, rappeler les idées principales et proposer une ouverture pertinente si utile."],["À quoi sert un pitch professionnel d’une minute ?","À présenter rapidement une idée, le besoin auquel elle répond et son intérêt."],["Pour défendre une solution dans un pitch, quel enchaînement logique utiliser ?","Besoin → solution → valeur apportée → preuve → prochaine étape."],["Que faire pour un pitch d’une minute ?","Garder un message central et un exemple fort."],["Pourquoi chronométrer ses répétitions ?","Pour adapter le contenu sans parler trop vite."]],"quiz":[["Pour préparer un exposé sur « la digitalisation des banques », quelle formulation constitue une problématique plutôt qu’un simple thème ?",["La digitalisation des banques","Les services bancaires numériques","Comment la digitalisation modifie-t-elle la relation client des banques ?"],2,"Une problématique pose une question délimitée ; un thème se contente d’annoncer un domaine."],["Quelle formulation constitue une problématique ?",["Les réseaux sociaux en général","Les entreprises et Internet","Comment une PME peut-elle utiliser les réseaux sociaux sans nuire à sa réputation ?","L’importance des réseaux sociaux"],2,"La question définit un enjeu précis à traiter."],["Que doit annoncer l’introduction d’un exposé ?",["Tous les exemples détaillés","La conclusion complète","Les réponses aux questions du public","Le sujet, la problématique et le plan"],3,"L’introduction prépare le parcours de l’exposé."],["Quelle pratique aide à structurer le développement ?",["Développer chaque idée avec un exemple et une transition","Répéter l’introduction à chaque partie","Présenter toutes les idées dans une seule phrase","Ajouter des informations sans lien"],0,"Chaque partie doit contribuer au raisonnement."],["Quel rôle joue la conclusion ?",["Introduire un argument majeur inédit","Répondre à la problématique et synthétiser","Réciter toutes les diapositives","Ouvrir une nouvelle partie complète"],1,"La conclusion rassemble la réponse et les points essentiels."],["Dans un pitch, pourquoi commencer par un besoin ?",["Pour éviter de présenter la solution","Pour allonger artificiellement le discours","Pour montrer le problème auquel la solution répond","Pour remplacer toute preuve"],2,"Le besoin donne du sens à la solution présentée."],["Que faut-il privilégier dans un pitch d’une minute ?",["Quatre exemples détaillés","Une lecture intégrale du dossier","Un historique complet du projet","Un message central et une preuve pertinente"],3,"La brièveté impose de sélectionner l’essentiel."],["Un pitch dépasse largement le temps prévu. Quelle correction est la plus utile ?",["Hiérarchiser les idées, retirer les détails secondaires et répéter le pitch chronométré","Conserver toutes les informations mais accélérer le débit jusqu’à tenir le temps","Supprimer l’étape de décision demandée pour gagner quelques secondes","Réduire uniquement les pauses, sans revoir l’organisation du message"],0,"On ajuste le contenu plutôt que d’accélérer excessivement."]],"map":[["Définir le sujet et la problématique","Un thème indique de quoi l’on parle ; une problématique formule une question précise à laquelle"],["Préparer l’introduction","L’introduction capte l’attention, présente le sujet, formule la problématique et annonce le pla"],["Organiser le développement","Le développement suit deux ou trois idées principales, chacune appuyée par une explication et u"],["Conclure utilement","La conclusion répond à la problématique, rappelle l’essentiel et peut ouvrir sur une question o"],["Le pitch professionnel","Un pitch est une présentation courte destinée à faire comprendre rapidement une idée ou un proj"],["Adapter le pitch au temps disponible","Pour un pitch d’une minute, il faut choisir un message central et un seul exemple convaincant"]]},{"title":"Cohérence, explication et argumentation","notes":[["Construire un discours cohérent","Un discours cohérent relie ses idées par un fil logique. Chaque phrase apporte une information utile à la suivante. Par exemple : « La plateforme est pratique, mais elle coûte cher. De plus, les salariés doivent être formés. Nous devons donc comparer les bénéfices et les coûts avant de décider. »"],["Utiliser les connecteurs","Les connecteurs rendent visibles les relations entre les idées : « d’abord » pour organiser, « de plus » pour ajouter, « cependant » pour opposer, « parce que » pour justifier et « donc » pour conclure. Leur rôle n’est pas de décorer le texte, mais de rendre le raisonnement plus facile à suivre."],["Reformuler sans déformer","Reformuler consiste à exprimer la même idée plus clairement, sans modifier son sens. Une phrase trop vague comme « le système pose problème » peut devenir « le logiciel bloque lors de l’enregistrement des dossiers ». Une bonne reformulation conserve les faits, précise les termes et évite d’inventer une cause."],["Expliquer pour faire agir","Expliquer une procédure signifie présenter des étapes dans un ordre compréhensible. « Ouvrez le navigateur, saisissez votre identifiant, puis confirmez » indique ce qu’il faut faire. Pour une consigne complexe, on précise aussi le résultat attendu et la manière de vérifier que l’action a réussi."],["Argumenter plutôt que juger","Argumenter consiste à soutenir une position par une raison et, si possible, une preuve. « Cette solution est intéressante » est un jugement peu étayé. « Cette solution pourrait réduire les délais, car le test pilote montre une baisse de 20 % » est un argument qui peut être discuté et vérifié."],["Distinguer expliquer et convaincre","Expliquer vise d’abord la compréhension d’un fonctionnement ; argumenter cherche à faire accepter une position. « Le tableau de bord classe les demandes par statut » explique. « Nous devrions l’adopter, car il évite les relances dispersées » argumente. Une même présentation peut passer de l’un à l’autre."]],"cards":[["Dans un exposé oral, à quoi sert un connecteur logique entre deux idées ?","À signaler leur relation : addition, cause, conséquence, opposition ou ordre."],["Dans un exposé, quelle relation exprime le connecteur « cependant » entre deux idées ?","Une opposition ou concession : la deuxième idée nuance la première."],["Dans un exposé, quelle relation exprime le connecteur « donc » ?","Une conséquence ou une conclusion découlant de l’idée précédente."],["Reformuler signifie-t-il changer les faits ?","Non, exprimer la même idée plus clairement."],["Quelle différence entre expliquer et argumenter ?","Expliquer clarifie ; argumenter justifie une position."],["Dans l’argumentation orale, quels éléments rendent un argument convaincant ?","Une idée défendue, une raison explicite et une preuve ou un exemple pertinent."],["Pourquoi préciser les étapes d’une procédure ?","Pour rendre l’action réalisable et vérifiable."],["Pourquoi « c’est une bonne idée » est-il faible ?","C’est un jugement sans justification."]],"quiz":[["Un intervenant dit « l’outil est coûteux ; cependant, il réduit les délais ». Quel lien le connecteur exprime-t-il ?",["Une opposition ou concession","Une cause","Une chronologie"],0,"« Cependant » introduit une nuance opposée à l’idée précédente."],["« Le coût augmente ; donc nous devons revoir le budget ». « Donc » exprime…",["Une addition","Une chronologie","Une illustration","Une conséquence"],3,"La seconde proposition découle de la première."],["Quelle reformulation conserve le sens de « le logiciel bloque à l’enregistrement » ?",["L’enregistrement ne fonctionne pas correctement","Le logiciel présente un défaut général permanent, pas limité à cette étape","La panne vient nécessairement d’une erreur humaine lors de la saisie","Le logiciel a perdu toutes les données déjà enregistrées"],0,"La reformulation précise le problème sans inventer de cause."],["« Ouvrez Paramètres puis Confidentialité » sert principalement à…",["Négocier","Expliquer une procédure","Exprimer une inquiétude","Évaluer une personnalité"],1,"La phrase décrit des étapes à suivre."],["Quel énoncé constitue un argument plutôt qu’un simple jugement ?",["Je préfère ce logiciel","Cette solution est magnifique","Le test pilote montre une baisse de 20 % des délais","Ce projet me plaît"],2,"Une donnée vérifiable soutient la position."],["Quelle différence entre expliquer et argumenter ?",["Expliquer consiste à défendre une décision ; argumenter consiste à présenter une définition","Expliquer et argumenter sont identiques dès qu’un exemple est utilisé","Argumenter consiste seulement à reformuler un fait de manière neutre","Expliquer rend un phénomène compréhensible ; argumenter défend une position avec des raisons"],3,"Expliquer clarifie le fonctionnement ou les causes d’un fait. Argumenter justifie un point de vue à l’aide de raisons et de preuves."],["« De plus » introduit principalement…",["Un élément supplémentaire","Une conclusion","Une objection","Une opposition"],0,"Le connecteur ajoute une information ou un argument."],["Une reformulation correcte doit…",["Élargir le sens en ajoutant des informations non vérifiées","Préserver les faits et le sens tout en clarifiant la formulation","Transformer la réserve du destinataire en approbation implicite","Réduire le propos à une conclusion plus forte que l’énoncé initial"],1,"Reformuler ne doit pas déformer l’information."]],"map":[["Construire un discours cohérent","Un discours cohérent relie ses idées par un fil logique"],["Utiliser les connecteurs","Les connecteurs rendent visibles les relations entre les idées : « d’abord » pour organiser, « "],["Reformuler sans déformer","Reformuler consiste à exprimer la même idée plus clairement, sans modifier son sens"],["Expliquer pour faire agir","Expliquer une procédure signifie présenter des étapes dans un ordre compréhensible"],["Argumenter plutôt que juger","Argumenter consiste à soutenir une position par une raison et, si possible, une preuve"],["Distinguer expliquer et convaincre","Expliquer vise d’abord la compréhension d’un fonctionnement ; argumenter cherche à faire accept"]]},{"title":"Traiter les objections et maîtriser l’oral","notes":[["Comprendre une objection","Une objection exprime une inquiétude, un désaccord ou une demande de précision : coût trop élevé, résistance au changement ou sécurité des données. Elle ne doit pas être traitée comme une attaque personnelle. La première étape consiste à écouter et à identifier le problème concret soulevé."],["Reformuler avant de répondre","Reformuler montre que l’objection a été comprise : « Si je comprends bien, vous craignez que la formation prenne trop de temps ». Cette étape évite de répondre à côté du sujet. On peut ensuite demander une précision, reconnaître une limite réelle et proposer une réponse adaptée."],["Répondre avec une preuve ou une solution","À « Le budget est trop élevé », on peut répondre : « Comparons le coût de l’outil au temps actuellement consacré aux tâches manuelles ». À « Les salariés ne voudront pas changer », on peut proposer un groupe pilote et une formation. La réponse doit être réaliste et ne pas promettre un résultat non démontré."],["Distinguer les trois démarches","Expliquer décrit un fonctionnement ou une procédure ; argumenter justifie une décision ; neutraliser une objection répond à une réserve exprimée. « Cliquez sur Paramètres » explique. « Adoptons cet outil car il réduit les délais » argumente. « Vous craignez son coût : comparons les économies possibles » traite une objection."],["Gérer le temps et la voix","La maîtrise de l’oral demande une progression lisible, un débit régulier, des pauses et une attention au temps. Il est utile de répéter les transitions et la conclusion. Une voix audible et des phrases suffisamment courtes permettent de maintenir la compréhension sans multiplier les effets de style."],["Terminer par une action claire","À la fin d’une présentation professionnelle, il faut préciser ce qui a été décidé ou demandé : prochaine réunion, responsable d’une tâche ou date limite. Une conclusion qui se contente de « merci » peut laisser l’équipe sans orientation. La communication vise aussi la coordination et l’exécution."]],"cards":[["Face à une objection exprimée pendant une réunion, quelle est la première étape recommandée ?","Écouter et identifier précisément la réserve avant d’y répondre."],["Pendant un échange professionnel, pourquoi reformuler une objection avant de répondre ?","Pour vérifier la réserve exacte et éviter de répondre à un problème différent."],["Comment répondre à une objection de coût ?","Comparer coûts et bénéfices avec des éléments vérifiables."],["Que proposer face à la résistance au changement ?","Un test pilote, de l’accompagnement et une formation."],["En réponse à une objection, quelle différence entre argumenter et neutraliser ?","Argumenter défend une position ; neutraliser traite une réserve précise déjà exprimée."],["Pourquoi éviter les promesses sans preuve ?","Elles affaiblissent la crédibilité du discours."],["Comment maintenir un bon rythme oral ?","Débit régulier, pauses et transitions claires."],["Pour clore une réunion de projet, quelles informations faut-il rappeler aux participants ?","Décisions prises, responsables, échéances et prochaine étape."]],"quiz":[["Un client affirme « votre solution coûte trop cher ». Quelle première réponse est la plus appropriée selon la méthode étudiée ?",["Rejeter immédiatement son avis","Demander quels coûts lui semblent problématiques","Promettre une réduction sans vérifier"],1,"Avant d’argumenter, il faut identifier précisément l’objection afin d’y répondre sur des faits."],["Quelle réponse traite le mieux l’objection sur le coût ?",["Mettre le coût en regard des économies attendues, en précisant les hypothèses","Proposer une réduction immédiate sans clarifier le périmètre du projet","Répondre par la popularité de l’outil sans analyser les coûts","Déplacer la discussion vers le calendrier sans répondre sur le budget"],0,"La comparaison répond à la réserve avec un raisonnement vérifiable."],["Face à la crainte du changement, quelle proposition est pertinente ?",["Imposer l’outil sans explication","Organiser un pilote et accompagner l’équipe","Annuler toute formation","Éviter de consulter les utilisateurs"],1,"Un test pilote permet d’évaluer les difficultés concrètes."],["« Le tableau affiche les dossiers en cours » correspond surtout à…",["Une objection","Une négociation","Une explication","Un jugement de valeur"],2,"L’énoncé décrit une fonction de l’outil."],["« Adoptons cet outil car il réduit les relances » correspond surtout à…",["Une simple procédure","Une objection","Une fonction phatique","Une argumentation"],3,"La phrase défend une décision par une raison."],["« Vous craignez un retard : testons d’abord sur un groupe » correspond à…",["Une réponse à une objection","Une description neutre","Une annonce de thème","Une fonction poétique"],0,"La proposition répond directement à une réserve exprimée."],["Quelle pratique améliore la maîtrise de l’oral ?",["Lire plus vite que prévu","Préparer les transitions et répéter avec un chronomètre","Multiplier les termes techniques","Éviter les pauses"],1,"Les répétitions aident à contrôler le temps et la progression."],["À la fin d’une réunion de projet, que faut-il clarifier ?",["Le plan de la prochaine réunion sans attribuer les tâches actuelles","Le nombre d’interventions de chaque participant pendant la réunion","Les décisions prises, les responsables des actions et les échéances","Le seul résultat financier, même si des décisions restent à exécuter"],2,"L’équipe doit savoir quelles actions suivre."]],"map":[["Comprendre une objection","Une objection exprime une inquiétude, un désaccord ou une demande de précision : coût trop élev"],["Reformuler avant de répondre","Reformuler montre que l’objection a été comprise : « Si je comprends bien, vous craignez que la"],["Répondre avec une preuve ou une solution","À « Le budget est trop élevé », on peut répondre : « Comparons le coût de l’outil au temps actu"],["Distinguer les trois démarches","Expliquer décrit un fonctionnement ou une procédure ; argumenter justifie une décision ; neutra"],["Gérer le temps et la voix","La maîtrise de l’oral demande une progression lisible, un débit régulier, des pauses et une att"],["Terminer par une action claire","À la fin d’une présentation professionnelle, il faut préciser ce qui a été décidé ou demandé : "]]}];
